`timescale 1ns / 1ps
// Repro, bucket A: high run must last exactly `duty` cycles.
module tb_pwm_pulse_width;
    reg        clk = 1'b0;
    reg        rst = 1'b1;
    reg  [3:0] duty = 4'd3;
    wire       pwm;
    reg [8*64-1:0] nonce;
    integer passed = 0;
    integer failed = 0;
    integer n, k, run;
    reg prev, found, high;

    pwm_gen #(.PERIOD(8)) dut (.clk(clk), .rst(rst), .duty(duty), .pwm(pwm));

    always #5 clk = ~clk;

    task check(input cond, input [8*40-1:0] label);
        begin
            if (cond) passed = passed + 1;
            else begin
                failed = failed + 1;
                $display("CHECK FAIL [%0s] at %0t", label, $time);
            end
        end
    endtask

    task wait_rise(output ok);
        integer c;
        begin
            ok = 1'b0; c = 0; prev = pwm;
            while (!ok && c < 40) begin
                @(posedge clk); #1;
                if (!prev && pwm) ok = 1'b1;
                prev = pwm; c = c + 1;
            end
        end
    endtask

    task measure_high(output integer len);
        begin
            len = 1; high = 1'b1;
            while (high && len < 40) begin
                @(posedge clk); #1;
                if (pwm) len = len + 1; else high = 1'b0;
            end
        end
    endtask

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        repeat (3) @(posedge clk);
        #1 rst = 1'b0;
        for (n = 0; n < 3; n = n + 1) begin
            wait_rise(found);
            check(found, "pulse_width.rise_seen");
            if (found) begin
                measure_high(run);
                $display("pulse_width: high run %0d (expect 3)", run);
                check(run == 3, "pulse_width.high_run_eq_duty");
            end
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
