module tb_pwm_period;
    reg        clk = 1'b0;
    reg        rst = 1'b1;
    reg  [3:0] duty = 4'd3;
    wire       pwm;
    reg [8*64-1:0] nonce;
    integer passed = 0;
    integer failed = 0;
    integer n, gap;
    reg prev, found;

    pwm_gen #(.PERIOD(8)) dut (.clk(clk), .rst(rst), .duty(duty), .pwm(pwm));

    always #5 clk = ~clk;

    task check(input cond, input [8*40-1:0] label);
        begin
            if (cond) passed = passed + 1;
            else begin
                failed = failed + 1;
                $display("CHECK FAIL [%0s] at %0t", label, $time);
            end
        end
    endtask

    // Waits for the next rising edge; len = cycles waited.
    task wait_rise(output ok, output integer len);
        begin
            ok = 1'b0; len = 0; prev = pwm;
            while (!ok && len < 40) begin
                @(posedge clk); #1;
                len = len + 1;
                if (!prev && pwm) ok = 1'b1;
                prev = pwm;
            end
        end
    endtask

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        repeat (3) @(posedge clk);
        #1 rst = 1'b0;
        wait_rise(found, gap);
        check(found, "period.first_rise_seen");
        for (n = 0; n < 3; n = n + 1) begin
            wait_rise(found, gap);
            $display("period: rise-to-rise %0d (expect 8)", gap);
            check(found && gap == 8, "period.rise_to_rise_eq_8");
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
