// Repro, bucket C: a duty change in mid-period must take effect next period.
module tb_pwm_duty_update;
    reg        clk = 1'b0;
    reg        rst = 1'b1;
    reg  [3:0] duty = 4'd2;
    wire       pwm;
    reg [8*64-1:0] nonce;
    integer passed = 0;
    integer failed = 0;
    integer base, cur, nxt;
    reg prev, found, high;

    pwm_gen #(.PERIOD(8)) dut (.clk(clk), .rst(rst), .duty(duty), .pwm(pwm));

    always #5 clk = ~clk;

    task check(input cond, input [8*40-1:0] label);
        begin
            if (cond) passed = passed + 1;
            else begin
                failed = failed + 1;
                $display("CHECK FAIL [%0s] at %0t", label, $time);
            end
        end
    endtask

    task wait_rise(output ok);
        integer c;
        begin
            ok = 1'b0; c = 0; prev = pwm;
            while (!ok && c < 40) begin
                @(posedge clk); #1;
                if (!prev && pwm) ok = 1'b1;
                prev = pwm; c = c + 1;
            end
        end
    endtask

    task measure_high(output integer len);
        begin
            len = 1; high = 1'b1;
            while (high && len < 40) begin
                @(posedge clk); #1;
                if (pwm) len = len + 1; else high = 1'b0;
            end
        end
    endtask

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        base = 0; cur = 0; nxt = 0;
        repeat (3) @(posedge clk);
        #1 rst = 1'b0;
        // Baseline period at duty 2.
        wait_rise(found);
        check(found, "duty_update.baseline_rise_seen");
        if (found) measure_high(base);
        // Next period: change duty right after its first clock.
        wait_rise(found);
        check(found, "duty_update.change_rise_seen");
        if (found) begin
            duty = 4'd5;
            measure_high(cur);
        end
        $display("duty_update: baseline %0d, changed period %0d", base, cur);
        check(found && cur == base, "duty_update.mid_period_change_deferred");
        // Following period should use the new duty.
        wait_rise(found);
        check(found, "duty_update.next_rise_seen");
        if (found) measure_high(nxt);
        $display("duty_update: next period %0d (expect > %0d)", nxt, base);
        check(found && nxt > base, "duty_update.new_duty_next_period");
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
